type pragma = string

type block =
  { code_lines : string list
  ; start_line : int
  }

type document =
  { pragmas : pragma list
  ; blocks : block list
  }

let drop_trailing_empty_line lines =
  match List.rev lines with
  | "" :: rest -> List.rev rest
  | _ -> lines

let is_pragma_line line =
  String.length line > 0 && line.[0] = '#'

let is_output_line line =
  String.length line > 0 && line.[0] = '>'

let trim_pragma line =
  String.sub line 1 (String.length line - 1) |> String.trim

let parse lines =
  let lines = drop_trailing_empty_line lines in
  let rec take_pragmas acc count = function
    | line :: rest when is_pragma_line line -> take_pragmas (trim_pragma line :: acc) (count + 1) rest
    | rest -> List.rev acc, count, rest
  in
  let pragmas, pragma_count, remaining = take_pragmas [] 0 lines in
  let base_line = pragma_count + 1 in
  let add_block line_no current start_line acc =
    match current with
    | [] -> acc
    | code ->
      let start = match start_line with Some s -> s | None -> line_no in
      { code_lines = List.rev code; start_line = start } :: acc
  in
  let rec loop line_no current start_line acc = function
    | [] ->
      add_block line_no current start_line acc |> List.rev
    | line :: rest ->
      let trimmed = String.trim line in
      if is_output_line line then
        loop (line_no + 1) current start_line acc rest
      else if trimmed = "" then
        let acc = add_block line_no current start_line acc in
        loop (line_no + 1) [] None acc rest
      else
        let start_line = match start_line with None -> Some line_no | Some s -> Some s in
        loop (line_no + 1) (line :: current) start_line acc rest
  in
  let blocks = loop base_line [] None [] remaining in
  { pragmas; blocks }

let has_pragma doc name = List.exists (( = ) name) doc.pragmas
